package envelope

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"sync"
	"testing"
)

const (
	testHomeID = "dh_0123456789abcdef0123456789abcdef"
	testKeyID  = "key_11111111111111111111111111111111"
	testDocID  = "doc_33333333333333333333333333333333"
	// Generated by src/document_encryption.py at 3f4f125 with key bytes(range(32)),
	// nonce 07 repeated 12 times, blob context below, and plaintext b"fixture".
	// This is synthetic interoperability evidence, not a real credential.
	pythonVectorHex = ""
	canonicalBlob   = `{"algorithm":"AES-256-GCM","data_home_id":"dh_0123456789abcdef0123456789abcdef","key_id":"key_11111111111111111111111111111111","object_id":"doc_33333333333333333333333333333333","purpose":"blob","version":1}`
)

func testKey() []byte {
	key := make([]byte, KeyBytes)
	for i := range key {
		key[i] = byte(i)
	}
	return key
}

func blobContext() Context {
	return Context{DataHomeID: testHomeID, KeyID: testKeyID, Purpose: "blob", ObjectID: testDocID}
}

func ledgerContext() Context {
	context := blobContext()
	context.Purpose, context.ObjectID = "ledger", "ledger"
	return context
}

func goldenVector(t testing.TB) []byte {
	t.Helper()
	data, err := hex.DecodeString(pythonVectorHex)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func encrypted(t testing.TB, plaintext []byte, context Context) []byte {
	t.Helper()
	data, err := Encrypt(plaintext, testKey(), context)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func rawEnvelope(header []byte) []byte {
	data := make([]byte, prefixBytes+len(header)+NonceBytes+TagBytes)
	copy(data, magic)
	data[len(magic)] = Version
	binary.BigEndian.PutUint32(data[len(magic)+1:prefixBytes], uint32(len(header)))
	copy(data[prefixBytes:], header)
	return data
}

func assertCode(t testing.TB, err error, code string) {
	t.Helper()
	var typed *Error
	if !errors.As(err, &typed) || typed.Code != code {
		t.Fatalf("expected code %s, got %T: %v", code, err, err)
	}
	if typed.Error() != (&Error{Code: code}).Error() {
		t.Fatalf("unexpected error message: %q", typed.Error())
	}
}

func assertDecryptError(t testing.TB, data, key []byte, context Context, code string) {
	t.Helper()
	result, err := Decrypt(data, key, context)
	assertCode(t, err, code)
	if result.Header != (Header{}) || result.Plaintext != nil {
		t.Fatal("failed decryption exposed a header or plaintext")
	}
}

func TestPythonGoldenVector(t *testing.T) {
	data := goldenVector(t)
	if len(data) != 254 || fmt.Sprintf("%x", sha256.Sum256(data)) != "fcd6e5031529b712ea8d394a19f2645134099242da85f86ada5681dd61995c60" {
		t.Fatal("Python fixture bytes changed")
	}
	got, err := Decrypt(data, testKey(), blobContext())
	if err != nil || string(got.Plaintext) != "fixture" {
		t.Fatalf("Python fixture did not decrypt: %v", err)
	}
	actual := encrypted(t, []byte("fixture"), blobContext())
	headerEnd := prefixBytes + len(canonicalBlob)
	if !bytes.Equal(actual[:headerEnd], data[:headerEnd]) {
		t.Fatal("Go prefix/header differs from Python's canonical bytes")
	}
	if string(actual[prefixBytes:headerEnd]) != canonicalBlob {
		t.Fatal("canonical header changed")
	}
}

func TestRoundTrip(t *testing.T) {
	binaryData := make([]byte, 1024)
	for i := range binaryData {
		binaryData[i] = byte(i)
	}
	tests := []struct {
		name      string
		plaintext []byte
		context   Context
	}{
		{"empty_blob", []byte{}, blobContext()},
		{"nil_blob", nil, blobContext()},
		{"empty_ledger", nil, ledgerContext()},
		{"binary", binaryData, blobContext()},
		{"ledger", []byte(`{"documents":[],"version":1}`), ledgerContext()},
		{"unicode", []byte("Synthetic résumé 📄\x00\xff"), blobContext()},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			key := testKey()
			keyBefore, plaintextBefore := bytes.Clone(key), bytes.Clone(test.plaintext)
			data, err := Encrypt(test.plaintext, key, test.context)
			if err != nil {
				t.Fatal(err)
			}
			before := bytes.Clone(data)
			header, err := Inspect(data)
			if err != nil {
				t.Fatal(err)
			}
			decrypted, err := Decrypt(data, key, test.context)
			if err != nil || decrypted.Header != header || !bytes.Equal(decrypted.Plaintext, test.plaintext) {
				t.Fatalf("round trip failed: %v", err)
			}
			if !bytes.Equal(before, data) || !bytes.Equal(keyBefore, key) || !bytes.Equal(plaintextBefore, test.plaintext) {
				t.Fatal("codec modified an input slice")
			}
			if len(decrypted.Plaintext) > 0 {
				decrypted.Plaintext[0] ^= 1
				if !bytes.Equal(before, data) || !bytes.Equal(plaintextBefore, test.plaintext) {
					t.Fatal("decrypted output aliases input memory")
				}
			}
			if len(test.plaintext) > 0 {
				data[0] ^= 1
				if !bytes.Equal(plaintextBefore, test.plaintext) {
					t.Fatal("encrypted output aliases plaintext input")
				}
			}
		})
	}
}

func TestFreshNoncesAndConcurrentCalls(t *testing.T) {
	const count = 32
	var wg sync.WaitGroup
	outputs := make(chan []byte, count)
	errorsFound := make(chan error, count)
	for range count {
		wg.Go(func() {
			data, err := Encrypt([]byte("same synthetic plaintext"), testKey(), blobContext())
			if err == nil {
				_, err = Decrypt(data, testKey(), blobContext())
			}
			if err != nil {
				errorsFound <- err
				return
			}
			outputs <- data
		})
	}
	wg.Wait()
	close(outputs)
	close(errorsFound)
	for err := range errorsFound {
		t.Fatal(err)
	}
	seen := map[string]bool{}
	for data := range outputs {
		headerEnd := prefixBytes + int(binary.BigEndian.Uint32(data[len(magic)+1:prefixBytes]))
		nonce := string(data[headerEnd : headerEnd+NonceBytes])
		if seen[nonce] {
			t.Fatal("encryption reused a nonce")
		}
		seen[nonce] = true
	}
	if len(seen) != count {
		t.Fatal("missing concurrent result")
	}
}

func TestContextValidation(t *testing.T) {
	tests := []struct {
		name   string
		change func(*Context)
	}{
		{"empty_home", func(c *Context) { c.DataHomeID = "" }},
		{"uppercase_home", func(c *Context) { c.DataHomeID = strings.ToUpper(c.DataHomeID) }},
		{"short_home", func(c *Context) { c.DataHomeID = c.DataHomeID[:len(c.DataHomeID)-1] }},
		{"long_home", func(c *Context) { c.DataHomeID += "0" }},
		{"home_newline", func(c *Context) { c.DataHomeID += "\n" }},
		{"bad_hex", func(c *Context) { c.DataHomeID = "dh_" + strings.Repeat("g", 32) }},
		{"hex_punctuation", func(c *Context) { c.KeyID = "key_" + strings.Repeat(":", 32) }},
		{"non_ascii", func(c *Context) { c.DataHomeID = "dh_" + strings.Repeat("é", 16) }},
		{"invalid_utf8", func(c *Context) { c.KeyID = "key_" + strings.Repeat("\xff", 32) }},
		{"empty_key_id", func(c *Context) { c.KeyID = "" }},
		{"key_id_wrong_prefix", func(c *Context) { c.KeyID = "doc_" + strings.Repeat("0", 32) }},
		{"empty_purpose", func(c *Context) { c.Purpose = "" }},
		{"unknown_purpose", func(c *Context) { c.Purpose = "resume" }},
		{"purpose_case", func(c *Context) { c.Purpose = "Blob" }},
		{"blob_ledger_id", func(c *Context) { c.ObjectID = "ledger" }},
		{"ledger_doc_id", func(c *Context) { c.Purpose = "ledger" }},
		{"empty_object", func(c *Context) { c.ObjectID = "" }},
		{"object_newline", func(c *Context) { c.ObjectID += "\n" }},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			context := blobContext()
			test.change(&context)
			data, err := Encrypt(nil, testKey(), context)
			assertCode(t, err, CodeInvalid)
			if data != nil {
				t.Fatal("invalid context returned encrypted bytes")
			}
			assertDecryptError(t, goldenVector(t), testKey(), context, CodeInvalid)
		})
	}
}

func TestKeyValidationAndFailurePrecedence(t *testing.T) {
	for _, size := range []int{0, 1, 16, 24, 31, 33, 64} {
		t.Run(fmt.Sprint(size), func(t *testing.T) {
			key := make([]byte, size)
			data, err := Encrypt(nil, key, Context{})
			assertCode(t, err, CodeKeyInvalid)
			if data != nil {
				t.Fatal("invalid key returned output")
			}
			assertDecryptError(t, nil, key, Context{}, CodeKeyInvalid)
		})
	}
	assertDecryptError(t, nil, testKey(), Context{}, CodeInvalid)
	assertDecryptError(t, nil, testKey(), ledgerContext(), CodeInvalid)
	data := goldenVector(t)
	data[len(data)-1] ^= 1
	assertDecryptError(t, data, testKey(), ledgerContext(), CodeContextMismatch)
	assertDecryptError(t, data, testKey(), blobContext(), CodeAuthenticationFailed)
}

func TestContextMismatchAndAuthentication(t *testing.T) {
	data := goldenVector(t)
	contexts := []Context{blobContext(), blobContext(), blobContext(), ledgerContext()}
	contexts[0].DataHomeID = "dh_" + strings.Repeat("a", 32)
	contexts[1].KeyID = "key_" + strings.Repeat("b", 32)
	contexts[2].ObjectID = "doc_" + strings.Repeat("c", 32)
	for i, context := range contexts {
		t.Run(fmt.Sprint(i), func(t *testing.T) {
			assertDecryptError(t, data, testKey(), context, CodeContextMismatch)
		})
	}
	wrongKey := bytes.Repeat([]byte{0xff}, KeyBytes)
	assertDecryptError(t, data, wrongKey, blobContext(), CodeAuthenticationFailed)
	headerEnd := prefixBytes + len(canonicalBlob)
	for _, offset := range []int{headerEnd, headerEnd + NonceBytes - 1, headerEnd + NonceBytes, len(data) - TagBytes, len(data) - 1} {
		t.Run(fmt.Sprintf("flip_%d", offset), func(t *testing.T) {
			tampered := bytes.Clone(data)
			tampered[offset] ^= 1
			if _, err := Inspect(tampered); err != nil {
				t.Fatalf("Inspect unexpectedly authenticated the payload: %v", err)
			}
			assertDecryptError(t, tampered, testKey(), blobContext(), CodeAuthenticationFailed)
		})
	}
	assertDecryptError(t, data[:len(data)-1], testKey(), blobContext(), CodeAuthenticationFailed)
	assertDecryptError(t, append(bytes.Clone(data), 0), testKey(), blobContext(), CodeAuthenticationFailed)

	// A syntactically valid changed header still fails AAD authentication even
	// when the caller supplies the changed context, not the original one.
	changed := blobContext()
	changed.DataHomeID = "dh_" + strings.Repeat("a", 32)
	tampered := bytes.Replace(data, []byte(testHomeID), []byte(changed.DataHomeID), 1)
	assertDecryptError(t, tampered, testKey(), blobContext(), CodeContextMismatch)
	assertDecryptError(t, tampered, testKey(), changed, CodeAuthenticationFailed)
}

func TestInspectIsUnauthenticated(t *testing.T) {
	data := rawEnvelope([]byte(canonicalBlob)) // Zero nonce and fabricated tag.
	header, err := Inspect(data)
	if err != nil || header.ObjectID != testDocID {
		t.Fatalf("valid header was not inspected: %v", err)
	}
	assertDecryptError(t, data, testKey(), blobContext(), CodeAuthenticationFailed)
}

func TestRejectMalformedHeaders(t *testing.T) {
	headers := map[string][]byte{
		"empty_object":          []byte(`{}`),
		"array":                 []byte(`[]`),
		"null":                  []byte(`null`),
		"invalid_utf8":          []byte{0xff, 0xfe},
		"bom":                   append([]byte{0xef, 0xbb, 0xbf}, []byte(canonicalBlob)...),
		"trailing_newline":      []byte(canonicalBlob + "\n"),
		"leading_space":         []byte(" " + canonicalBlob),
		"trailing_object":       []byte(canonicalBlob + `{}`),
		"duplicate_same_value":  []byte(canonicalBlob[:len(canonicalBlob)-1] + `,"version":1}`),
		"duplicate_other_value": []byte(canonicalBlob[:len(canonicalBlob)-1] + `,"purpose":"ledger"}`),
		"escaped_field":         []byte(strings.Replace(canonicalBlob, `"algorithm"`, `"\u0061lgorithm"`, 1)),
		"escaped_value":         []byte(strings.Replace(canonicalBlob, `"AES`, `"\u0041ES`, 1)),
		"uppercase_field":       []byte(strings.Replace(canonicalBlob, `"algorithm"`, `"Algorithm"`, 1)),
		"whitespace":            []byte(strings.ReplaceAll(canonicalBlob, ":", ": ")),
		"reordered":             []byte(strings.Replace(canonicalBlob, `"purpose":"blob","version":1`, `"version":1,"purpose":"blob"`, 1)),
		"deeply_nested":         []byte(strings.Repeat("[", 1000) + strings.Repeat("]", 1000)),
		"unpaired_surrogate":    []byte(strings.Replace(canonicalBlob, `AES-256-GCM`, `\ud800`, 1)),
		"unknown_field":         []byte(canonicalBlob[:len(canonicalBlob)-1] + `,"private_title":"synthetic-private-marker"}`),
		"unsupported_algorithm": []byte(strings.Replace(canonicalBlob, "AES-256-GCM", "AES-CBC", 1)),
		"unicode_algorithm":     []byte(strings.Replace(canonicalBlob, "AES-256-GCM", "AES-256-GCΜ", 1)),
		"unsupported_version":   []byte(strings.Replace(canonicalBlob, `"version":1`, `"version":2`, 1)),
		"non_integer_version":   []byte(strings.Replace(canonicalBlob, `"version":1`, `"version":1.0`, 1)),
		"exponent_version":      []byte(strings.Replace(canonicalBlob, `"version":1`, `"version":1e0`, 1)),
		"negative_zero_version": []byte(strings.Replace(canonicalBlob, `"version":1`, `"version":-0`, 1)),
		"overflow_version":      []byte(strings.Replace(canonicalBlob, `"version":1`, `"version":18446744073709551616`, 1)),
	}
	var fields map[string]json.RawMessage
	if err := json.Unmarshal([]byte(canonicalBlob), &fields); err != nil {
		t.Fatal(err)
	}
	for field := range fields {
		for _, value := range []string{`null`, `true`, `false`, `[]`, `{}`, `"1"`, `0`} {
			copyFields := make(map[string]json.RawMessage, len(fields))
			for key, raw := range fields {
				copyFields[key] = raw
			}
			copyFields[field] = json.RawMessage(value)
			header, err := json.Marshal(copyFields)
			if err != nil {
				t.Fatal(err)
			}
			headers[field+"_type_"+value] = header
		}
		copyFields := make(map[string]json.RawMessage, len(fields))
		for key, raw := range fields {
			if key != field {
				copyFields[key] = raw
			}
		}
		header, err := json.Marshal(copyFields)
		if err != nil {
			t.Fatal(err)
		}
		headers["missing_"+field] = header
	}
	for name, header := range headers {
		t.Run(name, func(t *testing.T) {
			data := rawEnvelope(header)
			got, err := Inspect(data)
			assertCode(t, err, CodeInvalid)
			if got != (Header{}) {
				t.Fatal("invalid header was returned")
			}
			assertDecryptError(t, data, testKey(), blobContext(), CodeInvalid)
		})
	}
}

func TestRejectMalformedFraming(t *testing.T) {
	data := goldenVector(t)
	for size := 0; size < prefixBytes+len(canonicalBlob)+NonceBytes+TagBytes; size++ {
		t.Run(fmt.Sprintf("truncated_%d", size), func(t *testing.T) {
			_, err := Inspect(data[:size])
			assertCode(t, err, CodeInvalid)
		})
	}
	for offset := 0; offset <= len(magic); offset++ {
		bad := bytes.Clone(data)
		bad[offset] ^= 0xff
		_, err := Inspect(bad)
		assertCode(t, err, CodeInvalid)
	}
	for _, length := range []uint32{0, 1, 2, MaxHeaderBytes, MaxHeaderBytes + 1, ^uint32(0)} {
		t.Run(fmt.Sprintf("header_length_%d", length), func(t *testing.T) {
			bad := bytes.Clone(data)
			binary.BigEndian.PutUint32(bad[len(magic)+1:prefixBytes], length)
			_, err := Inspect(bad)
			assertCode(t, err, CodeInvalid)
		})
	}
	_, err := Inspect(rawEnvelope(bytes.Repeat([]byte{' '}, MaxHeaderBytes)))
	assertCode(t, err, CodeInvalid)
}

func TestObjectAndEnvelopeSizeLimits(t *testing.T) {
	plaintext := make([]byte, MaxObjectBytes+1)
	for _, context := range []Context{blobContext(), Context{}} {
		data, err := Encrypt(plaintext, testKey(), context)
		assertCode(t, err, CodeSizeInvalid) // Size precedes context validation.
		if data != nil {
			t.Fatal("oversized content returned output")
		}
	}
	_, err := Encrypt(plaintext, nil, Context{})
	assertCode(t, err, CodeKeyInvalid) // Key precedes size validation.
	data := encrypted(t, plaintext[:MaxObjectBytes], blobContext())
	decrypted, err := Decrypt(data, testKey(), blobContext())
	if err != nil || !bytes.Equal(decrypted.Plaintext, plaintext[:MaxObjectBytes]) {
		t.Fatalf("maximum-sized object failed: %v", err)
	}
	if _, err := Inspect(data); err != nil {
		t.Fatal(err)
	}
	_, err = Inspect(append(data, 0)) // Object bound, below the total-envelope bound.
	assertCode(t, err, CodeInvalid)
	_, err = Inspect(make([]byte, MaxEnvelopeBytes+1))
	assertCode(t, err, CodeInvalid)
}

func TestErrorsAreSanitized(t *testing.T) {
	messages := map[string]string{
		CodeInvalid:              "Encrypted document envelope is invalid.",
		CodeKeyInvalid:           "Document encryption key must be exactly 32 bytes.",
		CodeSizeInvalid:          "Document content exceeds the supported encryption size.",
		CodeContextMismatch:      "Encrypted document envelope does not match the requested context.",
		CodeAuthenticationFailed: "Encrypted document authentication failed.",
	}
	for code, message := range messages {
		if got := (&Error{Code: code}).Error(); got != message {
			t.Fatalf("%s: unexpected message %q", code, got)
		}
	}
	privateMarker := "synthetic-private-marker"
	_, err := Inspect(rawEnvelope([]byte(`{"title":"` + privateMarker + `"}`)))
	assertCode(t, err, CodeInvalid)
	if strings.Contains(err.Error(), privateMarker) || strings.Contains(err.Error(), hex.EncodeToString(testKey())) {
		t.Fatal("error disclosed private input")
	}
	if (&Error{Code: privateMarker}).Error() != messages[CodeInvalid] {
		t.Fatal("unknown error code leaked into message")
	}
}
